1138	function saveStore(dataDir: string, store: Store): void {
1139	  const path = dataPath(dataDir);
1140	  // 临时文件名携带进程号与随机标识：同进程多次保存互不覆盖，崩溃后的遗留文件
1141	  // 也能凭进程号确认持有者已退出后再清理，绝不清除存活请求的临时文件。
1142	  const tmp = join(dataDir, `.${DATA_FILENAME}.${process.pid}.${Math.random().toString(36).slice(2)}.tmp`);
1143	  // 仅供本地回归检查使用的崩溃注入点（未设置时完全无作用）：
1144	  //   before-tmp  原子替换前（尚未写临时文件）被 kill，遗留锁、业务不生效
1145	  //   after-tmp   临时文件写完、rename 之前被 kill，遗留锁与临时文件、业务不生效
1146	  //   after-rename 原子替换之后、输出成功之前被 kill，完整提交保留
1147	  const crashPoint = process.env.STOCKROOM_TEST_CRASH;
1148	  if (crashPoint === 'before-tmp') process.kill(process.pid, 'SIGKILL');
1149	  let fd: number;
1150	  try {
1151	    mkdirSync(dataDir, { recursive: true });
1152	    fd = openSync(tmp, 'wx'); // 原子创建：同名（极小概率）直接失败而不是覆盖他人内容
1153	    try {
1154	      writeFileSync(fd, JSON.stringify(store, null, 2) + '\n', 'utf8');
1155	      fsyncSync(fd); // 内容落盘后再 rename，保证替换后即完整提交
1156	    } finally {
1157	      closeSync(fd);
1158	    }
1159	    if (crashPoint === 'after-tmp') process.kill(process.pid, 'SIGKILL');
1160	    renameSync(tmp, path);
1161	    if (crashPoint === 'after-rename') process.kill(process.pid, 'SIGKILL');
1162	  } catch (e) {
1163	    try {
1164	      unlinkSync(tmp); // 写入失败不留下本请求的半成品临时文件
1165	    } catch {
1166	      /* 临时文件不存在也无妨 */
1167	    }
1168	    throw new DataError(`保存数据失败，已有数据保持不变：${(e as Error).message}`);
1169	  }
1170	}
1171	
1172	// ---------- 多进程写入协调 ----------
1173	//
1174	// 同一数据目录的写请求用目录内的锁文件串行化：取得写入机会后才读取最新已提交
1175	// 状态，业务校验、去重与原子保存（临时文件 + rename）都在持有锁期间完成，因此
1176	// 并发请求的最终结果等价于某个完整串行执行顺序，流水序号与该顺序一致。锁文件
1177	// 位于数据目录内部，相对、绝对及符号链接路径经 realpath 归一后指向同一目录时
1178	// 共用同一把锁；不同目录各有自己的锁，互不阻塞。只读查询不创建也不检查锁文件。
1179	//
1180	// 锁协议（固定闸门 + 按进程命名的身份文件 + 唯一回收协调者）：
1181	//   - 每个写进程先 O_EXCL 创建自己的身份文件
1182	//     .stockroom.json.lock.<pid>.<nonce> 并写完整持有者信息（pid 在“文件名”里，
1183	//     内容在发布前写好），再用 link() 把它硬链接到固定闸门名
1184	//     .stockroom.json.lock：闸门已存在时 link 原子失败（EEXIST），不存在时原子
1185	//     成功，谁也不会覆盖谁。
1186	//   - 判定占用：闸门存在时取其 inode，找到与之同 inode 的身份文件（或协调者
1187	//     文件），其记录的 pid 仍存活就一律等待——哪怕内容暂时不完整，或持有者建锁
1188	//     后暂停很久，文件年龄与内容完整度从不作为接管依据。
1189	//   - 持有者进程退出后闸门成为遗留物。多个等待者先竞争唯一的“回收协调者”文件
1190	//     .stockroom.json.lock.coord（硬链接原子认领，存活期间稳定唯一，死协调者按
1191	//     死 pid 回收）：只有协调者能动闸门。回收用一次原子“替换 rename”
1192	//     （rename(自己的身份文件, 闸门)）无缝完成——闸门名全程存在、inode 被整体
1193	//     换成新持有者，没有“闸门短暂缺失被他人插队”的空隙；非协调者一律等待。
1194	//     因此回收者绝不可能移走另一个请求刚取得的闸门，多个恢复者只能串行取得
1195	//     写入机会；结束或失败时也只释放本进程自己的闸门/身份/协调者文件。
1196	//   - 异常退出若发生在原子替换之前，本次业务变动完全不生效；发生在替换之后，
1197	//     完整提交已保留（即使来不及输出成功），重试按已有结果去重。遗留临时文件、
1198	//     身份/协调者文件与回收物凭 pid 确认持有者已退出后由后续写入者清理，
1199	//     存活请求的文件一律不动。
1200	//
1201	// 等待有上限（默认 10 秒，可用环境变量 STOCKROOM_LOCK_WAIT_MS 按毫秒调整）：
1202	// 只接受十进制非负安全整数，0 表示仅尝试立即取得；非法或超出安全整数范围的
1203	// 配置在任何等待前报标准错误并以退出码 2 结束，绝不退化为无限等待。超时明确
1204	// 报错并以退出码 1 结束。
