1206	const LOCK_GATE = `.${DATA_FILENAME}.lock`; // 固定闸门名（也兼容旧版单文件锁）
1207	const LOCK_COORD = `.${DATA_FILENAME}.lock.coord`; // 回收协调者（稳定、唯一）
1208	const LOCK_PREFIX = `.${DATA_FILENAME}.lock.`; // 各进程身份文件此前缀
1209	const COORD_PREFIX = `.${DATA_FILENAME}.lock.coord.reclaimed.`; // 死协调者回收物
1210	const RECLAIM_PREFIX = `.${DATA_FILENAME}.lock.reclaimed.`; // 旧版本闸门回收物
1211	const TMP_PREFIX = `.${DATA_FILENAME}.`;
1212	const LOCK_WAIT_DEFAULT_MS = 10_000;
