1220	/** 解析并校验等待上限：仅接受纯十进制非负安全整数；0 = 仅立即尝试；非法配置抛用法错误（退出 2）。 */
1221	function lockWaitLimitMs(): number {
1222	  const raw = process.env.STOCKROOM_LOCK_WAIT_MS;
1223	  if (raw === undefined) return LOCK_WAIT_DEFAULT_MS;
1224	  // 必须整体是数字（含空白、小数点、符号均拒绝），避免把非法值悄悄解释为 0 或无限等待
1225	  if (!/^\d+$/.test(raw))
1226	    throw new UsageError(
1227	      `环境变量 STOCKROOM_LOCK_WAIT_MS 必须是非负整数毫秒（0 表示仅尝试立即取得），实际为：${raw}`,
1228	    );
1229	  const n = Number(raw);
1230	  if (!Number.isSafeInteger(n))
1231	    throw new UsageError(
1232	      `环境变量 STOCKROOM_LOCK_WAIT_MS 超出安全整数范围，拒绝启动（不能转换为无限等待）：${raw}`,
1233	    );
1234	  return n;
1235	}
