1250	/** 把（可能含符号链接的）数据目录归一为真实路径，使同一目录的不同写法共用一把锁。 */
1251	function resolveDataDir(dataDir: string): string {
1252	  try {
1253	    return realpathSync.native(dataDir);
1254	  } catch {
1255	    // 目录尚不存在：先归一父目录（父目录本身可能是符号链接），再拼上待创建的末级
1256	    const abs = resolve(dataDir);
1257	    const slash = Math.max(abs.lastIndexOf('/'), 0);
1258	    const parent = abs.slice(0, slash) || '/';
1259	    const base = abs.slice(slash + 1);
1260	    try {
1261	      return join(realpathSync.native(parent), base);
1262	    } catch {
