1268	/** 读取锁身份文件名中的 pid（.stockroom.json.lock.<pid>.<nonce>）；无法解析返回 null。 */
1269	function lockNamePid(name: string): number | null {
1270	  if (!name.startsWith(LOCK_PREFIX)) return null;
1271	  const rest = name.slice(LOCK_PREFIX.length);
1272	  if (rest === 'coord' || rest.startsWith('coord.')) return null; // 协调者文件，不是任何进程的身份文件
