/** 轮询等待某文件出现（仅供确定性回归的同步钩子使用）。 */
function waitForFile(path: string, timeoutMs = 60_000): void {
  const end = Date.now() + timeoutMs;
  for (;;) {
    try {
      statSync(path);
      return;
    } catch {
      if (Date.now() >= end) return;
      sleepSync(10);
    }
  }
}

/**
 * 仅供本地回归检查使用的确定性同步钩子（未设置 STOCKROOM_TEST_SYNC 时完全无作用）。
 * 配置为 JSON：{"point":"<同步点>","signal":"<到达时创建的文件>","wait":"<继续前等待出现的文件>"}。
 * 先 signal 后 wait：到达进程先留下到达标记，再阻塞直到测试驱动放行，从而可精确安排交错。
 * 同步点：coord-dead（读到旧协调者已死、搬走其文件前）、take-before（接任 rename 前）、
 * take-after（接任 rename 后、进入业务前）、release-before（释放闸门前）。
 */
function testSync(point: string): void {
  const raw = process.env.STOCKROOM_TEST_SYNC;
  if (raw === undefined) return;
  let cfg: { point?: string; signal?: string; wait?: string };
  try {
    cfg = JSON.parse(raw) as typeof cfg;
  } catch {
    return;
  }
  if (cfg.point !== point) return;
  if (cfg.signal) {
    try {
      writeFileSync(cfg.signal, `${process.pid}\n`);
    } catch {
      /* 测试钩子失败不影响正常流程 */
    }
  }
  if (cfg.wait) waitForFile(cfg.wait);
}

