        } catch (e3) {
          abandon();
          throw new DataError(`无法获取数据目录写入机会（接任锁闸门失败）：${(e3 as Error).message}`);
        }
        testSync('take-after');
        return finish(true); // 协调者身份随闸门持有到 release
