      if (amCoordinator) {
        // 自己是协调者但闸门已被合法存活持有者占据（接任前状态变化）：让贤。
        releaseCoordIfMine();
        amCoordinator = false;
      }
    } else if (amCoordinator) {
      // 自己是协调者但闸门属于存活进程：让贤并等待。
      releaseCoordIfMine();
      amCoordinator = false;
    }

    // 3) 闸门属于存活进程（或等待现任协调者完成回收）：在等待上限内轮询。
    if (limit === 0 || Date.now() >= deadline) {
      abandon();
      throw busyError();
    }
